#include "PluginEditor.h"
namespace {
const juce::Colour graphite{0xff111519},panel{0xff1c232a},brass{0xffd5ad68},ivory{0xfff2eee5};
constexpr std::array<const char*,8> fields{"tune","gain","pan","start","end","attack","release","filter"};
constexpr std::array<const char*,8> titles{"TUNE / st","GAIN / dB","PAN","START / fraction","END / fraction","ATTACK / ms","RELEASE / ms","LOW-PASS / Hz"};
void label(juce::Label& l,const juce::String& text){l.setText(text,juce::dontSendNotification);l.setColour(juce::Label::textColourId,ivory);l.setFont(juce::Font(juce::FontOptions(12)));}
}
DrumEditor::Style::Style(){setColourScheme(getDarkColourScheme());setColour(juce::TextButton::buttonColourId,panel);setColour(juce::TextButton::buttonOnColourId,brass.darker(.5f));setColour(juce::TextButton::textColourOffId,ivory);setColour(juce::TextButton::textColourOnId,ivory);setColour(juce::Slider::thumbColourId,brass);setColour(juce::Slider::trackColourId,brass);}
void DrumEditor::Style::drawRotarySlider(juce::Graphics& g,int x,int y,int w,int h,float position,float start,float end,juce::Slider&){
    auto bounds=juce::Rectangle<float>(static_cast<float>(x),static_cast<float>(y),static_cast<float>(w),static_cast<float>(h)).reduced(10);const float radius=std::max(4.0f,std::min(bounds.getWidth(),bounds.getHeight())*.5f-4);const auto centre=bounds.getCentre();
    g.setColour(graphite);g.fillEllipse(centre.x-radius,centre.y-radius,2*radius,2*radius);
    juce::Path track,arc;track.addCentredArc(centre.x,centre.y,radius,radius,0,start,end,true);arc.addCentredArc(centre.x,centre.y,radius,radius,0,start,start+position*(end-start),true);
    g.setColour(panel.brighter(.15f));g.strokePath(track,juce::PathStrokeType(4));g.setColour(brass);g.strokePath(arc,juce::PathStrokeType(4));
    const float angle=start+position*(end-start);g.drawLine(centre.x+std::sin(angle)*radius*.5f,centre.y-std::cos(angle)*radius*.5f,centre.x+std::sin(angle)*radius*.82f,centre.y-std::cos(angle)*radius*.82f,3);
}
DrumEditor::DrumEditor(DrumProcessor& p):AudioProcessorEditor(p),processor(p){
    setLookAndFeel(&style);setResizable(true,true);setResizeLimits(900,600,1600,1100);setSize(1100,720);
    for(int s=0;s<7;++s){auto& pad=pads[static_cast<size_t>(s)];addAndMakeVisible(pad);pad.setButtonText(ohsample::names[static_cast<size_t>(s)]);pad.setName(juce::String(ohsample::names[static_cast<size_t>(s)])+" select and audition");pad.setWantsKeyboardFocus(true);pad.onClick=[this,s]{auto* parameter=processor.parameters.getParameter("department");parameter->beginChangeGesture();parameter->setValueNotifyingHost(parameter->convertTo0to1(static_cast<float>(s)));parameter->endChangeGesture();select(s);processor.preview.store(s);};}
    for(auto* b:{&load,&hit,&save,&open,&ab,&resetButton,&exportButton,&panicButton}){addAndMakeVisible(*b);b->setName(b->getButtonText());b->setWantsKeyboardFocus(true);}
    load.onClick=[this]{choose(0);};hit.onClick=[this]{processor.preview.store(static_cast<int>(processor.parameters.getRawParameterValue("department")->load()));};save.onClick=[this]{choose(1);};open.onClick=[this]{choose(2);};ab.onClick=[this]{processor.switchAB();};resetButton.onClick=[this]{processor.resetKit();};exportButton.onClick=[this]{portable();};panicButton.onClick=[this]{processor.panic.store(true);processor.clipped.store(false);};
    for(auto* l:{&kit,&source,&status,&meter}){addAndMakeVisible(*l);label(*l,"");}
    kit.setEditable(false,true);kit.setName("Kit name: double click to rename");kit.onTextChange=[this]{processor.renameKit(kit.getText());};
    for(size_t i=0;i<detail.size();++i){auto& slider=detail[i];addAndMakeVisible(slider);slider.setSliderStyle(juce::Slider::LinearHorizontal);slider.setTextBoxStyle(juce::Slider::TextBoxRight,false,65,24);slider.setWantsKeyboardFocus(true);slider.setTooltip("Per-slot "+juce::String(titles[i])+". Envelope, region, reverse and tune apply to new hits.");addAndMakeVisible(detailNames[i]);label(detailNames[i],titles[i]);}
    for(size_t i=0;i<switches.size();++i){addAndMakeVisible(switches[i]);switches[i].setButtonText(i==0?"REVERSE":i==1?"MUTE":"SOLO");switches[i].setWantsKeyboardFocus(true);}
    constexpr std::array<const char*,3> ids{"body","character","space"};constexpr std::array<const char*,3> names{"BODY / weight + tail","CHARACTER / tone + drive","SPACE / stereo ambience"};
    for(size_t i=0;i<3;++i){addAndMakeVisible(macros[i]);macros[i].setName(ids[i]);macros[i].setSliderStyle(juce::Slider::RotaryHorizontalVerticalDrag);macros[i].setTextBoxStyle(juce::Slider::TextBoxBelow,false,80,24);macros[i].setDoubleClickReturnValue(true,i==2?.25:.5);macros[i].setTooltip(juce::String("Global ")+names[i]);macros[i].setWantsKeyboardFocus(true);addAndMakeVisible(macroNames[i]);label(macroNames[i],names[i]);macroNames[i].setJustificationType(juce::Justification::centred);macroAttachments[i]=std::make_unique<juce::AudioProcessorValueTreeState::SliderAttachment>(p.parameters,ids[i],macros[i]);}
    addAndMakeVisible(output);output.setName("output");output.setSliderStyle(juce::Slider::LinearHorizontal);output.setTextBoxStyle(juce::Slider::TextBoxRight,false,70,24);output.setTextValueSuffix(" dB");output.setTooltip("Output gain in dB. PANIC clears the latched clipping indicator.");output.setDoubleClickReturnValue(true,-6);output.setWantsKeyboardFocus(true);outputAttachment=std::make_unique<juce::AudioProcessorValueTreeState::SliderAttachment>(p.parameters,"output",output);
    current=processor.view();select(static_cast<int>(p.parameters.getRawParameterValue("department")->load()));timerCallback();startTimerHz(20);
}
DrumEditor::~DrumEditor(){stopTimer();setLookAndFeel(nullptr);}
void DrumEditor::select(int slot){selected=std::clamp(slot,0,6);for(size_t i=0;i<detail.size();++i){detailAttachments[i].reset();const auto id=DrumProcessor::slotId(selected,fields[i]);detail[i].setName(id);auto* parameter=processor.parameters.getParameter(id);detail[i].setDoubleClickReturnValue(true,parameter->convertFrom0to1(parameter->getDefaultValue()));detailAttachments[i]=std::make_unique<juce::AudioProcessorValueTreeState::SliderAttachment>(processor.parameters,id,detail[i]);}
    for(size_t i=0;i<switches.size();++i){switchAttachments[i].reset();const auto id=DrumProcessor::slotId(selected,i==0?"reverse":i==1?"mute":"solo");switches[i].setName(id);switchAttachments[i]=std::make_unique<juce::AudioProcessorValueTreeState::ButtonAttachment>(processor.parameters,id,switches[i]);}repaint();}
void DrumEditor::choose(int action){if(current.busy)return;const int destination=selected;const bool saving=action==1||action==3;chooser=std::make_unique<juce::FileChooser>(action==0?"Load or relink one sample":saving?"Save kit":"Load kit or portable kit",juce::File{},action==0?"*.wav;*.aif;*.aiff":action==3?"*.dhkit":"*.dhpreset;*.dhkit");
    juce::Component::SafePointer<DrumEditor> safe(this);chooser->launchAsync((saving?juce::FileBrowserComponent::saveMode|juce::FileBrowserComponent::warnAboutOverwriting:juce::FileBrowserComponent::openMode)|juce::FileBrowserComponent::canSelectFiles,[safe,action,destination](const juce::FileChooser& fc){if(!safe)return;auto file=fc.getResult();if(file==juce::File{})return;if(action==0)safe->processor.loadSample(destination,file);else if(action==1)safe->processor.saveKit(file,false);else if(action==3)safe->processor.saveKit(file,true,true);else safe->processor.loadKit(file);});}
void DrumEditor::portable(){juce::Component::SafePointer<DrumEditor> safe(this);juce::AlertWindow::showOkCancelBox(juce::MessageBoxIconType::QuestionIcon,"Portable kit sample rights","This export includes samples from both A and B. Continue only if you have permission to redistribute every included sample.","I have permission","Cancel",this,juce::ModalCallbackFunction::create([safe](int result){if(safe&&result)safe->choose(3);}));}
bool DrumEditor::isInterestedInFileDrag(const juce::StringArray& files){return files.size()==1;}
void DrumEditor::filesDropped(const juce::StringArray& files,int x,int y){if(files.size()!=1)return;int slot=selected;for(int s=0;s<7;++s)if(pads[static_cast<size_t>(s)].getBounds().contains(x,y))slot=s;select(slot);auto* p=processor.parameters.getParameter("department");p->beginChangeGesture();p->setValueNotifyingHost(p->convertTo0to1(static_cast<float>(slot)));p->endChangeGesture();processor.loadSample(slot,juce::File(files[0]));}
void DrumEditor::resized(){auto r=getLocalBounds().reduced(24);r.removeFromTop(50);auto toolbar=r.removeFromTop(32);kit.setBounds(toolbar.removeFromLeft(std::max(130,toolbar.getWidth()-570)));for(auto* b:{&save,&open,&ab,&resetButton,&exportButton}){toolbar.removeFromLeft(6);b->setBounds(toolbar.removeFromLeft(b==&exportButton?136:b==&ab?64:106));}
    r.removeFromTop(12);auto padRow=r.removeFromTop(54);const int pw=padRow.getWidth()/7;for(auto& pad:pads)pad.setBounds(padRow.removeFromLeft(pw).reduced(3,0));
    r.removeFromTop(12);auto sampleRow=r.removeFromTop(30);hit.setBounds(sampleRow.removeFromRight(96));sampleRow.removeFromRight(8);load.setBounds(sampleRow.removeFromRight(190));source.setBounds(sampleRow);
    r.removeFromTop(8);waveform=r.removeFromTop(getHeight()<680?78:110);r.removeFromTop(12);
    for(int row=0;row<2;++row){auto line=r.removeFromTop(56);const int cw=line.getWidth()/4;for(int col=0;col<4;++col){const auto i=static_cast<size_t>(row*4+col);auto cell=line.removeFromLeft(cw).reduced(5,0);detailNames[i].setBounds(cell.removeFromTop(20));detail[i].setBounds(cell.removeFromTop(30));}}
    auto footer=r.removeFromBottom(34);panicButton.setBounds(footer.removeFromLeft(80));footer.removeFromLeft(12);for(auto& toggle:switches)toggle.setBounds(footer.removeFromLeft(95));meter.setBounds(footer.removeFromRight(160));output.setBounds(footer);
    status.setBounds(r.removeFromBottom(28));const int mw=r.getWidth()/3;for(size_t i=0;i<3;++i){auto cell=r.removeFromLeft(mw);macroNames[i].setBounds(cell.removeFromTop(22));macros[i].setBounds(cell.reduced(25,0));}}
void DrumEditor::paint(juce::Graphics& g){g.fillAll(graphite);g.setColour(brass);g.setFont(juce::Font(juce::FontOptions(12,juce::Font::bold)));g.drawText("OMEGA HOUSE STUDIO",24,12,230,20,juce::Justification::left);g.setColour(ivory);g.setFont(juce::Font(juce::FontOptions(24,juce::Font::bold)));g.drawText("DRUM SUPPLY HEADQUARTERS",24,31,getWidth()-48,30,juce::Justification::left);
    g.setColour(panel);g.fillRoundedRectangle(waveform.toFloat(),8);g.setColour(ivory.withAlpha(.25f));g.drawHorizontalLine(waveform.getCentreY(),static_cast<float>(waveform.getX()+10),static_cast<float>(waveform.getRight()-10));
    if(current.snapshot){const auto& asset=current.snapshot->assets[static_cast<size_t>(selected)];if(asset.sample){const auto inner=waveform.reduced(12,10);g.setColour(brass);for(size_t i=0;i<256;++i){const float x=static_cast<float>(inner.getX())+static_cast<float>(i)*static_cast<float>(inner.getWidth())/256;const float amplitude=std::min(1.0f,asset.sample->waveform[i])*static_cast<float>(inner.getHeight())*.45f;g.drawVerticalLine(static_cast<int>(x),static_cast<float>(inner.getCentreY())-amplitude,static_cast<float>(inner.getCentreY())+amplitude);}
        for(const char* f:{"start","end"}){const float fraction=processor.parameters.getRawParameterValue(DrumProcessor::slotId(selected,f))->load();const float x=static_cast<float>(inner.getX())+fraction*static_cast<float>(inner.getWidth());g.setColour(ivory);g.drawVerticalLine(static_cast<int>(x),static_cast<float>(inner.getY()),static_cast<float>(inner.getBottom()));g.drawText(f,static_cast<int>(x)+(fraction>.5?-36:4),inner.getY(),38,20,juce::Justification::left);}}
        else {g.setColour(ivory);g.drawText("MISSING SAMPLE - LOAD / RELINK TO RECOVER",waveform,juce::Justification::centred);}}
}
void DrumEditor::timerCallback(){current=processor.view();for(auto* b:{&load,&save,&open,&ab,&resetButton,&exportButton})b->setEnabled(!current.busy);kit.setEditable(false,!current.busy);const float selection=processor.parameters.getRawParameterValue("department")->load();const int slot=std::isfinite(selection)?static_cast<int>(std::clamp(selection,0.0f,6.0f)):0;if(slot!=selected)select(slot);
    if(!kit.isBeingEdited())kit.setText(current.name,juce::dontSendNotification);kit.setTooltip(current.dirty?"Edited kit: save to keep these changes":"Saved kit");
    ab.setButtonText(current.ab==0?"A  /  b":"a  /  B");status.setText((current.dirty?"EDITED  |  ":"")+current.status,juce::dontSendNotification);
    if(current.snapshot){const auto& a=current.snapshot->assets[static_cast<size_t>(selected)];const auto metadata=a.sample?"  /  "+juce::String(static_cast<double>(a.sample->frames())/a.sample->rate,3)+" s  /  "+juce::String(a.sample->rate/1000,1)+" kHz":"  /  MISSING";source.setText(a.name+metadata,juce::dontSendNotification);
        for(size_t s=0;s<7;++s){const bool missing=current.snapshot->assets[s].missing;const bool muted=processor.parameters.getRawParameterValue(DrumProcessor::slotId(static_cast<int>(s),"mute"))->load()>.5f;const bool solo=processor.parameters.getRawParameterValue(DrumProcessor::slotId(static_cast<int>(s),"solo"))->load()>.5f;pads[s].setToggleState(static_cast<int>(s)==selected,juce::dontSendNotification);pads[s].setButtonText(juce::String(ohsample::names[s])+(missing?" / MISSING":muted?" / MUTE":solo?" / SOLO":""));}}
    const auto frame=processor.meterFrame.load(std::memory_order_acquire);if(frame==lastFrame)++stale;else {stale=0;lastFrame=frame;}displayedPeak=std::max(processor.peak.exchange(0),displayedPeak*.8f);if(stale>6)displayedPeak=0;
    meter.setText(processor.clipped.load()?"CLIP / PANIC to clear":stale>6?"OUTPUT / inactive":juce::String(juce::Decibels::gainToDecibels(displayedPeak,-90.0f),1)+" dBFS",juce::dontSendNotification);meter.setColour(juce::Label::textColourId,processor.clipped.load()?juce::Colour(0xffe46b65):ivory);repaint(waveform);
}
